"'$types = @{}; $names = @{}; $n = 0; $first = $null; $last = $null
foreach ($line in [System.IO.File]::ReadLines($f)) {
  $n++
  if ([string]::IsNullOrWhiteSpace($line)) { continue }
  try { $d = $line | ConvertFrom-Json } catch { $types["parse_error"] = 1 + [int]$types["parse_error"]; continue }
  $t = [string]$d.type
  $types[$t] = 1 + [int]$types[$t]
  if ($d.timestamp) { if (-not $first) { $first = $d.timestamp }; $last = $d.timestamp }
  if ($t -eq "response_item") {
    $pt = [string]$d.payload.type
    $key = "resp:" + $pt
    $names[$key] = 1 + [int]$names[$key]
    if ($pt -eq "function_call" -or $pt -eq "custom_tool_call" -or $pt -eq "local_shell_call") {
      $nm = [string]$d.payload.name
      if (-not $nm) { $nm = [string]$d.payload.action.type }
      $names["tool:" + $nm] = 1 + [int]$names["tool:" + $nm]
    }
  }
}
"lines: $n"; "first: $first"; "last: $last"
$types.GetEnumerator() | Sort-Object Value -Descending | ForEach-Object { "$($_.Key) $($_.Value)" }
"---"
$names.GetEnumerator() | Sort-Object Value -Descending | ForEach-Object { "$($_.Key) $($_.Value)" }'

